$ErrorActionPreference='Stop';Set-ExecutionPolicy -Scope Process Bypass -Force;Import-Module Invoke-AtomicRedTeam -Force
$guid='42dc4460-9aa6-45d3-b1a6-3955d34e1fe8';$root='C:\Windows\Temp\dc1-t1105';New-Item -ItemType Directory $root -Force|Out-Null;$source=Join-Path $root 'source.txt';$dest=Join-Path $root 'atomic-transfer.txt';Set-Content $source 'benign Detection Cycle 1 transfer fixture' -Encoding Ascii
$server=Start-Job -ScriptBlock {param($file)$l=[Net.HttpListener]::new();$l.Prefixes.Add('http://127.0.0.1:18765/');$l.Start();try{$c=$l.GetContext();$b=[IO.File]::ReadAllBytes($file);$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}finally{$l.Stop();$l.Close()}} -ArgumentList $source
try{Start-Sleep 2;Invoke-AtomicTest T1105 -TestGuids $guid -PathToAtomicsFolder 'C:\Tools\AtomicRedTeam\atomics' -InputArgs @{remote_file='http://127.0.0.1:18765/source.txt';destination_path=$dest} -Confirm:$false;if(-not(Wait-Job $server -Timeout 30)){throw 'server timeout'};if(-not(Test-Path $dest)){throw 'destination missing'};$sourceHash=(Get-FileHash $source).Hash;$destinationHash=(Get-FileHash $dest).Hash;if($sourceHash -ne $destinationHash){throw 'transfer hash mismatch'};[pscustomobject]@{AtomicGuid=$guid;SourceHash=$sourceHash;DestinationHash=$destinationHash;Completed=$true}|ConvertTo-Json -Compress|Set-Content (Join-Path $root 'positive.json')}finally{Get-Job|Stop-Job -ErrorAction SilentlyContinue;Get-Job|Remove-Job -Force -ErrorAction SilentlyContinue}
